const e="adrenal-crisis",i="Аддисонов криз / Острая надпочечниковая недостаточность",s="#8b5cf6",t=[{id:"cortisol",label:"Кортизол",layer:"raw",type:"lab",unit:"нмоль/л",normal:">250 (утро)",value:45,group:"endocrine",description:"Кортизол <138 нмоль/л утром — недостаточность. <50 — криз. Динамика после АКТГ."},{id:"acth",label:"АКТГ",layer:"raw",type:"lab",unit:"пг/мл",normal:"7.2-63.3",value:180,group:"endocrine",description:"АКТГ >100 пг/мл — первичная недостаточность (болезнь Аддисона). Низкий — вторичная."},{id:"sodium",label:"Натрий",layer:"raw",type:"lab",unit:"ммоль/л",normal:"136-145",value:120,group:"electrolytes",description:"Натрий <135 — гипонатриемия. Потеря через почки, дегидратация."},{id:"potassium",label:"Калий",layer:"raw",type:"lab",unit:"ммоль/л",normal:"3.5-5.1",value:6.2,group:"electrolytes",description:"Калий >5.0 — гиперкалиемия при первичной недостаточности. Гипокалиемия при вторичной."},{id:"glucose",label:"Глюкоза",layer:"raw",type:"lab",unit:"ммоль/л",normal:"3.9-5.6",value:2.8,group:"metabolic",description:"Глюкоза <3.3 — гипогликемия. Кортизол — контррегуляторный гормон."},{id:"creatinine",label:"Креатинин",layer:"raw",type:"lab",unit:"мкмоль/л",normal:"62-115",value:155,group:"renal",description:"Креатинин — предренальная азотемия при дегидратации, шоке."},{id:"hematocrit",label:"Гематокрит",layer:"raw",type:"lab",unit:"%",normal:"35-45",value:48,group:"hematology",description:"Гематокрит — повышение при дегидратации. Гемоконцентрация."},{id:"wbc",label:"Лейкоциты",layer:"raw",type:"lab",unit:"×10⁹/л",normal:"4.0-9.0",value:12.5,group:"hematology",description:"Лейкоциты — лейкопения при хронической недостаточности. Лейкоцитоз при стрессе."},{id:"calcium",label:"Кальций ионизированный",layer:"raw",type:"lab",unit:"ммоль/л",normal:"1.15-1.30",value:1.1,group:"electrolytes",description:"Кальций — гиперкальциемия при первичной недостаточности. Механизм неясен."},{id:"bp",label:"АД",layer:"raw",type:"lab",unit:"мм рт.ст.",normal:"120/80",value:80,group:"vitals",description:"АД — гипотензия, ортостатический коллапс. Не отвечает на инфузию без глюкокортикоидов."},{id:"hr",label:"ЧСС",layer:"raw",type:"lab",unit:"уд/мин",normal:"60-100",value:120,group:"vitals",description:"ЧСС — тахикардия при гиповолемии, гипотензии. Компенсаторная."},{id:"imaging_abdomen",label:"Рентген/УЗИ брюшной полости",layer:"raw",type:"instrumental",group:"imaging",description:"КТ/МРТ брюшной полости — кальциноз надпочечников, атрофия, геморрагия."},{id:"cosyntropin_test",label:"Тест с кортикотропином",layer:"raw",type:"lab",group:"endocrine",description:"Тест с синактеном — золотой стандарт. Кортизол <500 нмоль/л через 60 мин — недостаточность."},{id:"abdominal_pain",label:"Боль в животе",layer:"findings",type:"symptom",description:'Боль в животе — острая, неясной локализации. Может имитировать "острый живот".'},{id:"vomiting",label:"Рвота",layer:"findings",type:"symptom",description:"Рвота — тяжёлый криз. Усугубляет дегидратацию, электролитные нарушения."},{id:"diarrhea",label:"Диарея",layer:"findings",type:"symptom",description:"Диарея — хроническая недостаточность. Усугубляет дегидратацию, гипонатриемию."},{id:"hypotension",label:"Артериальная гипотензия",layer:"findings",type:"sign",severity:"тяжёлая",description:"Гипотензия — рефрактерная к инфузии. Требует гидрокортизона."},{id:"tachycardia",label:"Тахикардия",layer:"findings",type:"sign",description:"Тахикардия — компенсаторная при гиповолемии, гипотензии."},{id:"hypoglycemia",label:"Гипогликемия",layer:"findings",type:"sign",description:"Гипогликемия — опасна для мозга. Кортизол — ключевой контррегуляторный гормон."},{id:"hyperpigmentation",label:"Гиперпигментация кожи",layer:"findings",type:"sign",description:"Гиперпигментация — первичная недостаточность (АКТГ↑, МСХ). Складки, слизистые, шрамы."},{id:"dehydration",label:"Обезвоживание",layer:"findings",type:"sign",description:"Дегидратация — сухие слизистые, снижение тургора, ортостатическая гипотензия."},{id:"confusion",label:"Спутанность сознания",layer:"findings",type:"sign",description:"Спутанность — гипогликемия, гипонатриемия, гипотензия. Ранняя стадия комы."},{id:"weakness",label:"Слабость",layer:"findings",type:"symptom",description:"Слабость — хроническая недостаточность. Мышечная слабость, утомляемость."},{id:"dizziness",label:"Головокружение",layer:"findings",type:"symptom",description:"Головокружение — ортостатическая гипотензия, гипонатриемия, гипогликемия."},{id:"syncope",label:"Обморок",layer:"findings",type:"symptom",description:"Обморок — ортостатический коллапс, гипогликемия, тяжёлый шок."},{id:"dry_mucosa",label:"Сухость слизистых",layer:"findings",type:"sign",description:"Сухость слизистых — дегидратация. Ранний признак."},{id:"skin_turgor",label:"Снижение тургора кожи",layer:"findings",type:"sign",description:"Снижение тургора кожи — дегидратация. Проверяется на груди, лбу."},{id:"apathy",label:"Апатия/заторможенность",layer:"findings",type:"symptom",description:"Апатия — хроническая недостаточность. Психомоторное заторможение, депрессия."},{id:"addisonian_crisis",label:"Аддисонов криз",layer:"hypotheses",type:"diagnosis",prevalence:"2%",ptp:"low",description:"Аддисонов криз — острая недостаточность коры надпочечников. Гипотензия, гипогликемия, гипонатриемия, гиперкалиемия."},{id:"secondary_adrenal_insufficiency",label:"Вторичная надпочечниковая недостаточность",layer:"hypotheses",type:"diagnosis",prevalence:"1%",ptp:"low",description:"Вторичная недостаточность — гипопитуитаризм, длительные глюкокортикоиды. Нет гиперкалиемии, нормальная пигментация."},{id:"sepsis",label:"Сепсис",layer:"hypotheses",type:"diagnosis",prevalence:"10%",ptp:"medium",description:"Сепсис — может вызывать относительную недостаточность надпочечников. Кортизол может быть нормальным, но недостаточным для стресса."},{id:"acute_pancreatitis",label:"Острый панкреатит",layer:"hypotheses",type:"diagnosis",prevalence:"3%",ptp:"low",description:"Острый панкреатит — может сопровождать криз надпочечников. Дифференциальный диагноз при боли в животе."},{id:"gi_bleeding",label:"Желудочно-кишечное кровотечение",layer:"hypotheses",type:"diagnosis",prevalence:"2%",ptp:"low",description:"ЖК-кровотечение — пигментация слизистых при хронической недостаточности. Анемия, гипотензия."},{id:"hypovolemic_shock",label:"Гиповолемический шок",layer:"hypotheses",type:"diagnosis",prevalence:"5%",ptp:"low",description:"Гиповолемический шок — дегидратация, кровопотеря. Может сопровождать аддисонов криз."},{id:"diff_primary_vs_secondary",label:"Первичная vs Вторичная недостаточность",layer:"differential",type:"comparison"},{id:"diff_adrenal_vs_sepsis",label:"Аддисонов криз vs Сепсис",layer:"differential",type:"comparison"},{id:"guideline_endocrine_2016",label:"Endocrine Society Guidelines: Adrenal Insufficiency 2016",layer:"evidence",type:"guideline",grade:"A",year:2016,description:"Endocrine Society 2016 — диагностика и лечение первичной надпочечниковой недостаточности."},{id:"rct_hydrocortisone",label:"RCT: гидрокортизон 100 мг болюс vs инфузия",layer:"evidence",type:"rct",grade:"B",year:2017,n:124,description:"Когортные исследования — гидрокортизон 100 мг в/в болюс, затем 200 мг/сут. Спасает жизнь при кризе."},{id:"review_addison",label:"Review: Diagnosis and management of adrenal crisis",layer:"evidence",type:"review",grade:"A",year:2019,description:"Обзор — автоиммунный адреналит наиболее частая причина в развитых странах. Туберкулёз — в эндемичных регионах."}],r=[{source:"cortisol",target:"addisonian_crisis",type:"key_marker",weight:.95},{source:"cortisol",target:"secondary_adrenal_insufficiency",type:"key_marker",weight:.9},{source:"acth",target:"addisonian_crisis",type:"supports",weight:.9},{source:"acth",target:"secondary_adrenal_insufficiency",type:"supports",weight:.85},{source:"sodium",target:"addisonian_crisis",type:"supports",weight:.85},{source:"sodium",target:"sepsis",type:"supports",weight:.6},{source:"potassium",target:"addisonian_crisis",type:"supports",weight:.85},{source:"potassium",target:"hypovolemic_shock",type:"supports",weight:.5},{source:"glucose",target:"addisonian_crisis",type:"supports",weight:.8},{source:"glucose",target:"sepsis",type:"supports",weight:.6},{source:"glucose",target:"hypoglycemia",type:"supports",weight:.9},{source:"creatinine",target:"addisonian_crisis",type:"supports",weight:.65},{source:"creatinine",target:"sepsis",type:"supports",weight:.7},{source:"hematocrit",target:"addisonian_crisis",type:"supports",weight:.6},{source:"hematocrit",target:"hypovolemic_shock",type:"supports",weight:.7},{source:"wbc",target:"sepsis",type:"supports",weight:.8},{source:"wbc",target:"addisonian_crisis",type:"supports",weight:.55},{source:"calcium",target:"addisonian_crisis",type:"supports",weight:.6},{source:"cosyntropin_test",target:"addisonian_crisis",type:"confirms",weight:.95},{source:"cosyntropin_test",target:"secondary_adrenal_insufficiency",type:"confirms",weight:.9},{source:"imaging_abdomen",target:"acute_pancreatitis",type:"excludes",weight:.9},{source:"imaging_abdomen",target:"gi_bleeding",type:"excludes",weight:.85},{source:"bp",target:"addisonian_crisis",type:"supports",weight:.85},{source:"bp",target:"sepsis",type:"supports",weight:.8},{source:"bp",target:"hypovolemic_shock",type:"supports",weight:.9},{source:"hr",target:"addisonian_crisis",type:"supports",weight:.8},{source:"hr",target:"sepsis",type:"supports",weight:.75},{source:"hr",target:"hypovolemic_shock",type:"supports",weight:.8},{source:"abdominal_pain",target:"addisonian_crisis",type:"supports",weight:.75},{source:"abdominal_pain",target:"acute_pancreatitis",type:"supports",weight:.8},{source:"abdominal_pain",target:"gi_bleeding",type:"supports",weight:.7},{source:"vomiting",target:"addisonian_crisis",type:"supports",weight:.75},{source:"vomiting",target:"acute_pancreatitis",type:"supports",weight:.8},{source:"diarrhea",target:"addisonian_crisis",type:"supports",weight:.8},{source:"diarrhea",target:"sepsis",type:"supports",weight:.7},{source:"hypotension",target:"addisonian_crisis",type:"supports",weight:.9},{source:"hypotension",target:"sepsis",type:"supports",weight:.85},{source:"hypotension",target:"hypovolemic_shock",type:"supports",weight:.9},{source:"tachycardia",target:"addisonian_crisis",type:"supports",weight:.8},{source:"tachycardia",target:"sepsis",type:"supports",weight:.75},{source:"tachycardia",target:"hypovolemic_shock",type:"supports",weight:.8},{source:"hypoglycemia",target:"addisonian_crisis",type:"supports",weight:.85},{source:"hypoglycemia",target:"sepsis",type:"supports",weight:.6},{source:"hyperpigmentation",target:"addisonian_crisis",type:"supports",weight:.9},{source:"dehydration",target:"addisonian_crisis",type:"supports",weight:.8},{source:"dehydration",target:"hypovolemic_shock",type:"supports",weight:.85},{source:"confusion",target:"addisonian_crisis",type:"supports",weight:.75},{source:"confusion",target:"sepsis",type:"supports",weight:.8},{source:"weakness",target:"addisonian_crisis",type:"supports",weight:.8},{source:"weakness",target:"sepsis",type:"supports",weight:.7},{source:"dizziness",target:"addisonian_crisis",type:"supports",weight:.75},{source:"dizziness",target:"hypovolemic_shock",type:"supports",weight:.8},{source:"syncope",target:"addisonian_crisis",type:"supports",weight:.8},{source:"syncope",target:"hypovolemic_shock",type:"supports",weight:.85},{source:"dry_mucosa",target:"addisonian_crisis",type:"supports",weight:.75},{source:"dry_mucosa",target:"dehydration",type:"supports",weight:.9},{source:"skin_turgor",target:"addisonian_crisis",type:"supports",weight:.75},{source:"skin_turgor",target:"dehydration",type:"supports",weight:.9},{source:"apathy",target:"addisonian_crisis",type:"supports",weight:.75},{source:"addisonian_crisis",target:"diff_primary_vs_secondary",type:"compared_in",weight:1},{source:"secondary_adrenal_insufficiency",target:"diff_primary_vs_secondary",type:"compared_in",weight:1},{source:"addisonian_crisis",target:"diff_adrenal_vs_sepsis",type:"compared_in",weight:1},{source:"sepsis",target:"diff_adrenal_vs_sepsis",type:"compared_in",weight:1},{source:"addisonian_crisis",target:"guideline_endocrine_2016",type:"covered_in",weight:1},{source:"addisonian_crisis",target:"rct_hydrocortisone",type:"treated_in",weight:1},{source:"addisonian_crisis",target:"review_addison",type:"covered_in",weight:1},{source:"diff_primary_vs_secondary",target:"guideline_endocrine_2016",type:"described_in",weight:1}],a={addisonian_crisis:{description:"Аддисонов криз — острое обострение первичной недостаточности коры надпочечников. Смертность до 5% при своевременном лечении, до 50% без терапии.",criteria:["Клинические: гипотензия, гипогликемия, гипонатриемия, гиперкалиемия","Кортизол <250 нмоль/л (утро) или <500 нмоль/л при стрессе","АКТГ повышен (>2× верхней границы нормы) при первичной недостаточности","Тест с кортикотропином: кортизол <500 нмоль/л через 60 мин"],prevalence:"1-2% пациентов с болезнью Аддисона",complications:["Гиповолемический шок","Гипогликемическая кома","Острая почечная недостаточность","ДИК-синдром","Смерть"],treatment:["Гидрокортизон 100 мг в/в болюсно, затем 200 мг/сут инфузией","0.9% NaCl 1-2 л в/в (коррекция гипонатриемии и гиповолемии)","5% глюкоза при гипогликемии","Коррекция гиперкалиемии (глюконат кальция, инсулин+глюкоза при К+>6.5)","Поиск и лечение триггера (инфекция, отмена стероидов)","Минералокортикоиды (флудрокортизон) после стабилизации"],followup:"Пожизненная заместительная терапия глюкокортикоидами и минералокортикоидами, ношение браслета/карты"},secondary_adrenal_insufficiency:{description:"Вторичная надпочечниковая недостаточность — дефицит АКТГ гипофиза. Нет гиперкалиемии и гиперпигментации (альдостерон сохранён).",criteria:["Низкий кортизол","АКТГ нормальный или сниженный","Нет гиперкалиемии (альдостероновая ось интактна)","Нет гиперпигментации"],prevalence:"Редко встречается в острой форме",complications:["Гипогликемия","Гипотензия (менее выражена)","Гипонатриемия (синдром неадекватной секреции АДГ)"],treatment:["Гидрокортизон 100 мг в/в (без минералокортикоидов)","Коррекция гипогликемии","Лечение основного заболевания (опухоль гипофиза, отмена стероидов)"],followup:"Заместительная терапия глюкокортикоидами, без минералокортикоидов"}},o={diff_primary_vs_secondary:{headers:["Признак","Первичная (Аддисон)","Вторичная"],rows:[{feature:"АКТГ",primary:"Повышен",secondary:"Нормальный/снижен"},{feature:"Калий",primary:"Гиперкалиемия",secondary:"Нормальный"},{feature:"Натрий",primary:"Гипонатриемия",secondary:"Гипонатриемия (СНАДГ)"},{feature:"Гиперпигментация",primary:"Присутствует",secondary:"Отсутствует"},{feature:"Альдостерон",primary:"Снижен",secondary:"Нормальный"},{feature:"Минералокортикоиды",primary:"Нужны",secondary:"Не нужны"},{feature:"Причина",primary:"Аутоиммунная, инфекция, метастазы",secondary:"Отмена стероидов, опухоль гипофиза"}]}},n={guideline_endocrine_2016:{title:"Diagnosis and Treatment of Primary Adrenal Insufficiency: An Endocrine Society Clinical Practice Guideline",authors:"Bornstein SR et al.",journal:"J Clin Endocrinol Metab",year:2016,design:"Clinical guideline",grade:"A",key_findings:["Тест с кортикотропином — золотой стандарт диагностики","Гидрокортизон 100 мг болюсно + 200 мг/сут при кризе","Пациенты должны носить опознавательный браслет"],quality:"Высокое (GRADE: A)"},rct_hydrocortisone:{title:"Continuous vs bolus hydrocortisone in adrenal crisis",authors:"Boonen E et al.",journal:"J Clin Endocrinol Metab",year:2017,n:124,design:"RCT",grade:"B",key_findings:["Болюс + инфузия — стандарт терапии","Инфузия обеспечивает более стабильные уровни кортизола","Дозы >200 мг/сут не дают дополнительной пользы"],quality:"Среднее (одноцентровый RCT)"},review_addison:{title:"Diagnosis and management of adrenal crisis: a practical guide",authors:"Rushworth RL et al.",journal:"Intern Med J",year:2019,design:"Review",grade:"A",key_findings:["Смертность 0.5-5% при своевременном лечении","Инфекция и отмена стероидов — главные триггеры","Экстренная карта/браслет — обязательны"],quality:"Высокое (обзор экспертов)"}},p={addisonian_crisis:[{time:0,event:"Начало",bp:"100/70",glucose:"4.0",symptom:"Слабость, боль в животе"},{time:120,event:"2 часа",bp:"90/60",glucose:"3.5",symptom:"Рвота, диарея"},{time:240,event:"4 часа",bp:"80/50",glucose:"2.8",symptom:"Гипотензия, спутанность"},{time:300,event:"Диагностика",bp:"80/50",glucose:"2.8",symptom:"Кортизол 45, Na 120, K 6.2"},{time:315,event:"Терапия",bp:"75/45",glucose:"2.5",symptom:"Гидрокортизон 100 мг + NaCl + глюкоза"},{time:360,event:"1 час",bp:"90/55",glucose:"4.5",symptom:"Улучшение АД, ясное сознание"},{time:480,event:"3 часа",bp:"105/70",glucose:"5.5",symptom:"Стабилизация"},{time:1440,event:"24 часа",bp:"115/75",glucose:"5.8",symptom:"Гидрокортизон 50 мг × 4/сут"}]},c={id:e,label:i,color:s,nodes:t,links:r,details:a,comparisons:o,evidence:n,timelines:p};export{s as color,o as comparisons,c as default,a as details,n as evidence,e as id,i as label,r as links,t as nodes,p as timelines};
